import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Br18A9IS.js";var i=JSON.parse(`{"title":"WarpDrive Agent Skills","description":"","frontmatter":{},"headers":[],"relativePath":"skills/index.md","filePath":"skills/index.md"}`),a={name:`skills/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="warpdrive-agent-skills" tabindex="-1">WarpDrive Agent Skills <a class="header-anchor" href="#warpdrive-agent-skills" aria-label="Permalink to “WarpDrive Agent Skills”">​</a></h1><p>This section packages WarpDrive knowledge for AI coding agents — Claude, Copilot, Cursor, and similar tools — as small, focused, task-oriented skills.</p><p>Each skill is a single markdown file describing one thing to accomplish with WarpDrive: defining a schema, making a request, handling a mutation, and so on. Skills are grouped into directories by topic, the same way the <a href="/pr-preview/pr-11205/guides/">Guides</a> are, and published as the <a href="https://www.npmjs.com/package/@warp-drive/memory-alpha" target="_blank" rel="noreferrer"><code>@warp-drive/memory-alpha</code></a> npm package — named after the Federation&#39;s central archive of all recorded knowledge, minus the away-team incident that torched the original — so it can be installed into any project and consumed by an MCP server, a Claude Code skill, or adapted into tool-specific instruction files (Cursor rules, Copilot instructions, etc.).</p><p>Find the row below that matches what you&#39;re doing, or browse the categories in the sidebar.</p><table tabindex="0"><thead><tr><th>If you need to...</th><th>Go to</th></tr></thead><tbody><tr><td>Define a resource&#39;s shape — fields, relationships, identity — for the <code>Store</code></td><td><a href="/pr-preview/pr-11205/skills/schemas/define-a-resource-schema">Define a Resource Schema</a></td></tr><tr><td>Fetch or query remote data through the <code>Store</code> so it&#39;s cached and reactive</td><td><a href="/pr-preview/pr-11205/skills/requests/fetch-and-cache-data">Fetch and Cache Data</a></td></tr><tr><td>Set up HTTP mocking for a test suite with <code>@warp-drive/holodeck</code></td><td><a href="/pr-preview/pr-11205/skills/holodeck/set-up-holodeck">Set Up Holodeck</a></td></tr><tr><td>Mock a request in a test, or fix a mock that stopped matching</td><td><a href="/pr-preview/pr-11205/skills/holodeck/mock-http-requests-in-tests">Mock HTTP Requests in Tests</a></td></tr><tr><td>Re-record one holodeck mock, or review a test that sets <code>RECORD</code></td><td><a href="/pr-preview/pr-11205/skills/holodeck/using-record">Use RECORD in Holodeck Mocks</a></td></tr><tr><td>Look up a guide, upgrade note, or API reference page that no row above covers — a concept, an option, a signature</td><td><a href="/pr-preview/pr-11205/skills/docs/read-the-docs-as-markdown">Read the Docs as Markdown</a></td></tr><tr><td>You&#39;re contributing to WarpDrive itself, not just consuming it as a dependency</td><td><a href="/pr-preview/pr-11205/skills/contributors/">Contributor Skills</a></td></tr></tbody></table><p>This is the same routing table an AI agent uses to find a skill — it just links out to readable pages instead of naming files to read. If you&#39;re an AI agent rather than a human reader, don&#39;t start here — read the package&#39;s <code>skills/index.md</code> (or its <a href="https://www.npmjs.com/package/@warp-drive/memory-alpha" target="_blank" rel="noreferrer">README</a>) instead, which routes you directly to the one file you need without loading this page or any directory listing.</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};